def _ev(event_type, a, b, date, desc, geo, role, url, stype, conf, assets="", basis="", notes=""):
    return {"event_type": event_type, "party_a": a, "party_b": b, "date": date, "year": date[:4], "daf_or_asset_usd_moved": assets,
            "asset_basis": basis, "description": desc, "geography": geo, "cf_role": role, "source_url": url, "source_type": stype,
            "confidence": conf, "notes": notes}


